function wishPage(){
  const assets=Math.max(0,Engine.net(state)),gap=Math.max(0,state.goal-assets),weeks=Math.ceil(gap/state.weeklyPlan);
  return heading('心里，装着一个小愿望','愿望可以很具体，积累可以慢慢来。',link('换个愿望','edit-goal'))+`<div class="two-columns"><section class="stack"><article class="card wish-main"><span class="wish-big-art">${Art.telescope()}</span>${pill(`${icon('star',12)} 我想自己攒下来`,'purple')}<h2>${e(state.goalName||'第一架天文望远镜')}</h2><div class="wish-number">¥${money(assets)} <small>/ ${money(state.goal)}</small></div><div class="progress"><span style="width:${percent(assets/state.goal*100)}%"></span></div><p>${gap?`扣除计划欠款后，目标还差 ${money(gap)} 元，每一份努力都让它近一点。`:'扣除计划欠款后，已达到目标啦！取用前再看看产品期限和可用零钱。'}</p></article><article class="card"><h3>给愿望安排一个小计划</h3><p class="small muted mt8">如果每周通过劳动留下一笔钱，我想留……</p><div class="plan-amounts">${[1000,2000,3000].map(n=>`<button class="plan-btn ${state.weeklyPlan===n?'active':''}" data-action="weekly-plan" data-amount="${n}">每周 ${n/100} 元</button>`).join('')}</div><div class="insight">${icon('leaf',16)} ${gap?`只看新增劳动投入，按计划大约还需要 ${weeks} 周达到总积累目标。`:'你已经攒到了目标金额，和家长一起作下一次选择吧。'}</div><p class="tiny muted mt16">这是你可以调整的计划，未来收入不保证。持有中的钱还要考虑到期时间；实际购买以能取用的钱为准。</p></article></section><aside class="stack"><section class="card"><h3>今天，我可以安排多少？</h3><div class="receipt-total" style="font-size:35px;text-align:left;margin:17px 0">¥${money(state.wallet)}</div><p class="small muted">另有 ¥${money(Engine.holding(state))} 在计划中，需按约到期或提前取回。</p><div class="mt24">${button('申请领取一笔零钱','withdraw',`data-purpose="为${e(state.goalName||'第一架天文望远镜')}做准备"`,'secondary full')}</div></section><section class="card"><h3>想提前实现这个愿望？</h3><p class="small muted mt8">和家长约定预支、利息与每月还款，先看清未来的安排。</p><div class="mt16">${button('制定预支计划','go','data-view="loans"','secondary full')}</div></section><section class="tip-card"><h3>愿望也可以改变</h3><p>想法变了，可以重新安排。重要的是知道自己为什么这样选，而不是一定要把所有钱都留下。</p>${link('看看我的每一笔选择','go','data-view="wallet"')}</section></aside></div>`;
}
function projectionData(){
  const base=Math.max(0,Engine.net(state)),annualAdd=projectionContribute?state.weeklyPlan*52:0;
  let reinvest=base,principal=base,paidOut=0;const points=[{year:0,reinvest,simple:base,contribution:base}];
  for(let year=1;year<=projectionYears;year++){
    reinvest+=Money.interest(reinvest,state.rateBps,365)+annualAdd;
    paidOut+=Money.interest(principal,state.rateBps,365);principal+=annualAdd;
    points.push({year,reinvest,simple:principal+paidOut,contribution:base+annualAdd*year});
  }
  return points;
}
function projectionChart(points){
  const width=560,height=185,left=53,right=14,top=15,bottom=28;
  const max=Math.max(100,...points.map(p=>Math.max(p.reinvest,p.simple)))*1.12;
  const x=i=>left+i/(points.length-1)*(width-left-right),y=v=>top+(1-v/max)*(height-top-bottom);
  const line=key=>points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)} ${y(p[key]).toFixed(1)}`).join(' ');
  const area=`${line('reinvest')}L${x(points.length-1)} ${height-bottom}L${left} ${height-bottom}Z`;
  return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="收益继续投入与每期取出收益的长期积累对照"><defs><linearGradient id="growthArea" x2="0" y2="1"><stop stop-color="#c6d6a3" stop-opacity=".55"/><stop offset="1" stop-color="#dce8ca" stop-opacity=".1"/></linearGradient></defs>${[0,.5,1].map(f=>`<path d="M${left} ${y(max*f)}H${width-right}" stroke="#eceee3" stroke-dasharray="3 4"/><text x="${left-9}" y="${y(max*f)+4}" text-anchor="end" fill="#a0a68f" font-size="10">${Math.round(max*f/100)}</text>`).join('')}<path d="${area}" fill="url(#growthArea)"/><path d="${line('simple')}" stroke="#bba5cd" stroke-width="2.5" fill="none" stroke-dasharray="6 5"/><path d="${line('reinvest')}" stroke="#829e63" stroke-width="3" fill="none" stroke-linejoin="round"/><circle cx="${x(points.length-1)}" cy="${y(points[points.length-1].reinvest)}" r="4" fill="#829e63" stroke="#fff" stroke-width="2"/>${[0,Math.round((points.length-1)/2),points.length-1].map(i=>`<text x="${x(i)}" y="${height-5}" text-anchor="middle" fill="#a0a68f" font-size="10">${i===0?'现在':`${i} 年后`}</text>`).join('')}</svg>`;
}
function growthPage(){
  const points=projectionData(),last=points[points.length-1];
  const yieldEvents=state.history.filter(h=>h.type==='yield');
  return heading('每一点长大，都看得见','分清努力、收益与时间，各自做了什么。',pill('我的积累，我知道'))+`<div class="metrics mb16"><section class="card metric-card"><div class="number-label">自己劳动赚来的</div><div class="stat-num">¥${money(state.laborTotal)}</div><p class="tiny muted mt8">真实完成，再收获报酬</p></section><section class="card metric-card"><div class="number-label">家长按约结算的收益</div><div class="stat-num green">¥${money(state.bonusEarned)}</div><p class="tiny muted mt8">到期结算后，可以取用</p></section><section class="card metric-card"><div class="number-label">已经实际领取</div><div class="stat-num gold">¥${money(state.withdrawn)}</div><p class="tiny muted mt8">钱也可以变成生活里的快乐</p></section></div><div class="two-columns"><section class="card"><div class="between"><div><h2>如果，把收益也留下？</h2><p class="small muted mt8">以扣除计划待还后的积累 ¥${money(Math.max(0,Engine.net(state)))} 作假设对照</p></div>${pill(`${projectionYears} 年后`,'gold')}</div><div class="mt24"><label class="small muted" for="projection-years">看看未来多久</label><input id="projection-years" type="range" min="1" max="20" value="${projectionYears}" style="width:100%;accent-color:#8ba477;margin:14px 0" data-input="projection"><div class="between tiny muted"><span>1 年</span><span>10 年</span><span>20 年</span></div></div><div class="chart-wrap">${projectionChart(points)}</div><div class="chart-legend"><span><i></i>收益留下，继续参与积累</span><span><i class="dashed"></i>收益取出，不参与下一期</span></div><div class="growth-split"><div><small>收益继续投入</small><strong class="green">¥${money(last.reinvest)}</strong></div><div><small>同条件多积累</small><strong class="gold">+¥${money(last.reinvest-last.simple)}</strong></div></div><label class="check-row mt24"><input type="checkbox" data-input="contribution" ${projectionContribute?'checked':''}><span>也看看计划中的劳动投入：每周留 ${state.weeklyPlan/100} 元</span></label><p class="tiny muted mt16">仅为假设投影：把当前全部积累投入，每年按 ${fixedRate()} 结算并续存${projectionContribute?`，每年末再投入 ${money(state.weeklyPlan*52)} 元计划劳动所得`:''}。收益取出方案也计入已取出的收益。未来利率、收入与预算可能变化，投影不计入当前资产，也不代表家长已承诺未来兑付。</p></section><aside class="stack"><section class="tip-card">${Art.tree()}<h3>复利，是收益也参与下一次积累</h3><p>新的劳动报酬会增加本金。到期收益留下继续投入，也会让下一期的本金变多。<br><br>这两种变化，我们分开记。</p></section><section class="card"><h3>已经发生的收益故事</h3><div class="timeline mt24">${yieldEvents.length?yieldEvents.slice(0,4).map(h=>`<div class="timeline-item"><h4>${e(h.title)}</h4><p>${h.date} · 按约结算 ${money(h.amount)} 元</p></div>`).join(''):'<div class="timeline-item"><h4>第一笔到期收益，还在路上</h4><p>真实的积累需要时间。到期结算后，我们会在这里记下它。</p></div>'}</div>${link('看看持有进展','go','data-view="holdings"')}</section></aside></div>`;
}
function budgetMarkup(){
  const reserved=Engine.reserved(state),free=Engine.budgetFree(state),denominator=Math.max(1,state.budget);
  return `<div class="between"><div><h3>给孩子的收益承诺</h3><p class="small muted mt8">本阶段收益预算，与劳动报酬、本金分开记录</p></div>${pill('已有约定不变')}</div><div class="budget-meter"><span class="used" style="width:${state.bonusEarned/denominator*100}%"></span><span class="reserved" style="width:${reserved/denominator*100}%"></span></div><div class="budget-summary"><div><label>已承担收益</label><strong>¥${money(state.bonusEarned)}</strong></div><div><label>持有中已预留</label><strong class="gold">¥${money(reserved)}</strong></div><div><label>可作新承诺</label><strong class="green">¥${money(free)}</strong></div></div><div class="between tiny muted"><span>总预算 ¥${money(state.budget)}</span><span>结算后领取，不会重复扣预算</span></div>`;
}
function approvalMarkup(t){
  const isConfirm=t.status==='submitted';
  return `<article class="approval-card"><span class="ledger-icon">${icon('task',18)}</span><div class="grow"><h4>${e(t.name)}</h4><p>报酬 ${money(t.amount)} 元 · ${isConfirm?'孩子说已经完成':'已确认完成，报酬待兑现'}</p></div>${button(isConfirm?'确认完成':'兑现报酬',isConfirm?'approve-task':'pay-task',`data-id="${t.id}"`,'secondary small')}</article>`;
}
function parentPage(){
  const tasks=pendingTasks(),requests=pendingRequests();
  return heading('一起守护，孩子的小小成长','帮助孩子学会管理一笔属于自己的钱。',pill('家长空间','neutral'))+familyOverview()+`<section class="card parent-welcome mb16">${Art.mascot(90)}<div class="grow"><h2>${e(state.child)}的账户资产 ¥${money(Engine.assets(state))}</h2><p>其中劳动报酬累计 ${money(state.laborTotal)} 元，按约结算收益 ${money(state.bonusEarned)} 元。<br>钱的来处清楚，孩子的选择才更有分量。</p></div></section><div class="two-columns"><section class="stack"><article class="card">${budgetMarkup()}<div class="mt16">${link('查看预算与家庭约定','go','data-view="parent-budget"')}</div></article><article class="card"><div class="between"><h3>等你看一眼的劳动 ${tasks.length?`<span class="badge-count">${tasks.length}</span>`:''}</h3>${link('所有委托','go','data-view="parent-tasks"')}</div>${tasks.length?tasks.slice(0,3).map(approvalMarkup).join(''):`<p class="small muted mt16">暂时没有待确认的任务。孩子在现实中完成后，再回来提交。</p><div class="mt16">${button('回孩子端体验一次','go','data-view="tasks"','ghost small')}</div>`}</article></section><aside class="stack"><article class="card"><div class="between"><h3>领取申请</h3>${icon('wallet',19)}</div><div class="money big mt16">¥${money(Engine.pendingCash(state))}</div><p class="small muted mt8">${requests.length?'实际交付后，再确认这笔钱已经领取。':'当前没有待领取的申请。'}</p>${link('查看申请','go','data-view="parent-payouts"')}</article><article class="card"><h3>预支与每月还款</h3><p class="small muted mt8">待处理 ${state.loans.filter(l=>['pending','approved'].includes(l.status)).length} 份 · 计划待还 ¥${money(Engine.debt(state))}</p>${link('处理当前孩子的预支','go','data-view="parent-loans"')}</article><article class="tip-card"><h3>周末，聊聊这三个小问题</h3><p>这周哪一笔收入，是自己努力得到的？<br><br>为什么决定花掉或留下这笔钱？<br><br>到期的收益，是取出还是继续投入？</p>${link('一起翻翻成长手账','go','data-view="growth"')}</article></aside></div>`;
}
function parentTasksPage(){
  const needs=pendingTasks(),paid=state.tasks.filter(t=>t.status==='paid');
  return heading('认真完成，也认真兑现','先确认现实里的完成情况，再兑现事先约定的报酬。',button(`${icon('plus',16)} 新委托`,'new-task','','secondary small'))+`<div class="two-columns"><section class="stack"><article class="card"><h3>等待确认与兑现 ${needs.length?`<span class="badge-count">${needs.length}</span>`:''}</h3>${needs.length?needs.map(approvalMarkup).join(''):'<div class="empty mt16">目前没有待确认的劳动。<br>可以先到孩子端接下并完成一项委托。<div class="mt16">'+button('去孩子的委托板','go','data-view="tasks"','secondary small')+'</div></div>'}</article><article class="card"><h3>家庭的委托板</h3>${state.tasks.map(t=>`<div class="ledger-item"><span class="ledger-icon">${icon('task',18)}</span><div class="grow"><h4>${e(t.name)}</h4><p>${statusLabel[t.status]} · 事前约定 ${money(t.amount)} 元</p></div>${pill(t.status==='paid'?'已兑现':t.status==='available'?'可接取':t.status==='accepted'?'孩子进行中':'待处理',t.status==='paid'?'soft':'neutral')}</div>`).join('')}</article></section><aside class="tip-card"><h3>任务确认，与报酬兑现是两件事</h3><p>孩子提交后，先一起检查。确认完成，再确认报酬已实际交付，或已明确为孩子预留代管。<br><br>未兑现的报酬不会凭空增加孩子可用余额。</p><div class="divider"></div><p>已经兑现 ${paid.length} 项委托。劳动报酬独立于收益预算，不能用“收益预算不足”拒绝已约定的劳动报酬。</p></aside></div>`;
}
